/**
 * Open and awarded opportunities (/opportunity/<slug>), paginated past the old 1,000-row clip.
 * Generated by src/lib/seo/sitemap-sections.ts; listed in the sitemap index.
 */
import { renderUrlset, sitemapResponse, sitemapFailure } from '@/lib/seo/sitemap-xml';
import { opportunityEntries } from '@/lib/seo/sitemap-sections';

// Rendered per request, cached at the CDN (s-maxage 6h + 1 day stale-while-revalidate), so a
// read failure answers 503 instead of being frozen into a build artifact.
export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    return sitemapResponse(renderUrlset(await opportunityEntries()));
  } catch (err) {
    return sitemapFailure('opportunities', err);
  }
}
